// ============================================
// SHARED FUNCTIONS
// ============================================
function ensureArray(d) {
    if (Array.isArray(d)) return d;
    if (d && typeof d === 'object' && d.data && Array.isArray(d.data)) return d.data;
    return [];
}

function esc(t) {
    if (!t) return '';
    const d = document.createElement('div');
    d.textContent = String(t);
    return d.innerHTML;
}

function fmtCurrency(n) {
    return '৳ ' + Math.round(n || 0).toLocaleString('en-US');
}

function todayDate() {
    return new Date().toISOString().split('T')[0];
}

// ============================================
// APP FEATURES
// ============================================
const APP_FEATURES = {
    dashboard: true,
    customers: true,
    sales: true,
    collections: true,
    expenses: true,
    products: true,
    staff: true,
    suppliers: true,
    reports: true,
    printer: false
};

function isFeatureEnabled(key) {
    return APP_FEATURES[key] !== false;
}

function applyFeatureVisibility() {
    document.querySelectorAll('[data-feature]').forEach(el => {
        const feature = el.getAttribute('data-feature');
        if (!feature) return;
        el.hidden = !isFeatureEnabled(feature);
    });
}

function monthStartDate() {
    return new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().split('T')[0];
}

function buildPageUrl(path, params = {}, hash = '') {
    const qs = new URLSearchParams();
    Object.entries(params || {}).forEach(([key, value]) => {
        if (value === undefined || value === null || value === '') return;
        qs.set(key, String(value));
    });
    const query = qs.toString();
    return `${path}${query ? `?${query}` : ''}${hash ? `#${hash}` : ''}`;
}

function getCustomerDetailUrl(customerId, hash = '') {
    return buildPageUrl('customer-detail.html', { customer_id: customerId }, hash);
}

function getSaleDetailUrl(saleId, hash = '') {
    return buildPageUrl('sale-detail.html', { sale_id: saleId }, hash);
}

function getCollectionEntryUrl({ customerId = '', saleId = '', amount = '', notes = '' } = {}) {
    return buildPageUrl('collections.html', {
        customer_id: customerId,
        sale_id: saleId,
        amount,
        notes,
    });
}

function linkToUrl(url, label, className = '') {
    const cls = ['inline-link', className].filter(Boolean).join(' ');
    return `<a href="${esc(url)}" class="${cls}">${esc(label)}</a>`;
}

function customerLink(customerId, label) {
    if (!customerId) return esc(label || 'N/A');
    return `<a href="${esc(getCustomerDetailUrl(customerId))}" class="inline-link inline-customer">${esc(label || 'N/A')}</a>`;
}

function saleLink(saleId, label) {
    if (!saleId) return esc(label || 'N/A');
    return `<a href="${esc(getSaleDetailUrl(saleId))}" class="inline-link inline-sale">${esc(label || 'N/A')}</a>`;
}

function dueAmountLink(url, amountText) {
    return `<a href="${esc(url)}" class="inline-link inline-due">${esc(amountText)}</a>`;
}

function paymentLinkForCustomer(customerId, amountText, label = null) {
    return dueAmountLink(getCollectionEntryUrl({ customerId }), label || amountText);
}

function paymentLinkForSale(saleId, customerId, amountText, label = null) {
    return dueAmountLink(getCollectionEntryUrl({ customerId, saleId }), label || amountText);
}

// ============================================
// SHARED ACCOUNTING HELPERS
// ============================================
function getSaleTotalAmount(sale) {
    return parseFloat(sale?.total_amount ?? sale?.grandTotal ?? 0) || 0;
}

function getSalePaidAmount(sale) {
    const explicitPaid = parseFloat(sale?.paid_amount ?? sale?.paid ?? 0) || 0;
    if (explicitPaid > 0) return explicitPaid;

    // Backward compatibility: older records may store the payment only in linked collections.
    const saleId = sale?.id;
    if (!saleId) return 0;

    try {
        if (typeof collections !== 'undefined' && Array.isArray(collections)) {
            return collections
                .filter(c => (c.sale_id || c.saleId) == saleId)
                .reduce((sum, c) => sum + (parseFloat(c.amount || 0) || 0), 0);
        }
    } catch (e) {}

    return 0;
}

function getSaleDueAmount(sale) {
    if (!sale) return 0;
    const total = getSaleTotalAmount(sale);
    const paid = getSalePaidAmount(sale);
    const derivedDue = Math.max(0, total - paid);
    const explicitDue = sale.due_amount ?? sale.due;
    if (explicitDue === undefined || explicitDue === null || explicitDue === '') {
        return derivedDue;
    }
    const parsedDue = Math.max(0, parseFloat(explicitDue) || 0);
    return total > 0 ? derivedDue : parsedDue;
}

function getGeneralCollectionAmount(collections, customerId) {
    if (!Array.isArray(collections)) return 0;
    return collections
        .filter(c => (c.customer_id || c.customerId) == customerId && !(c.sale_id || c.saleId))
        .reduce((sum, c) => sum + (parseFloat(c.amount || 0) || 0), 0);
}

function getCustomerFinancialSummary(customerId, sales = [], collections = [], customers = []) {
    const openingBalance = parseFloat(customers.find(c => c.id == customerId)?.opening_balance || 0) || 0;
    const customerSales = Array.isArray(sales) ? sales.filter(s => (s.customer_id || s.customerId) == customerId) : [];
    const salesTotal = customerSales.reduce((sum, sale) => sum + getSaleTotalAmount(sale), 0);
    const paidOnSales = customerSales.reduce((sum, sale) => sum + getSalePaidAmount(sale), 0);
    const dueOnSales = customerSales.reduce((sum, sale) => sum + getSaleDueAmount(sale), 0);
    const generalCollections = getGeneralCollectionAmount(collections, customerId);
    const currentDue = Math.max(0, openingBalance + dueOnSales - generalCollections);
    return {
        openingBalance,
        salesTotal,
        paidOnSales,
        dueOnSales,
        generalCollections,
        currentDue,
        totalPaid: paidOnSales + generalCollections,
    };
}

// ============================================
// SHARED PRINT FUNCTION (No blank pages)
// ============================================
function printHTMLContent(html, options = {}) {
    const printableHtml = String(html || '');
    const title = options.title || 'Print';
    if (typeof window.printHTMLContent === 'function' && window.printHTMLContent !== printHTMLContent) {
        return window.printHTMLContent(printableHtml, {
            title,
            mode: options.mode || 'thermal',
            requireNative: options.requireNative !== false,
        });
    }
    const nativePrinter = window.NijerAppPrinter || window.AndroidPrinter;
    if (nativePrinter && typeof nativePrinter.printDocument === 'function') {
        nativePrinter.printDocument(JSON.stringify({
            title,
            html: printableHtml,
            text: options.text || '',
            url: window.location.href,
            requireNative: true,
        }));
        return true;
    }
    throw new Error('Native printer bridge is not available.');
}

