// ============================================
// SHARED NAVIGATION
// ============================================
const SHARED_NAV_ITEMS = [
    { key: 'index', href: 'index.html', label: '📊 Dashboard', cls: 'btn btn-ghost btn-sm' },
    { key: 'customers', href: 'customers.html', label: '👥 Customers', cls: 'btn btn-outline btn-sm' },
    { key: 'sales', href: 'sales.html', label: '➕ New Sale', cls: 'btn btn-outline btn-sm' },
    { key: 'collections', href: 'collections.html', label: '💵 Collection', cls: 'btn btn-outline btn-sm' },
    { key: 'expenses', href: 'expenses.html', label: '💸 Expenses', cls: 'btn btn-outline btn-sm' },
    { key: 'products', href: 'products.html', label: '📦 Products', cls: 'btn btn-outline btn-sm' },
    { key: 'staff', href: 'staff.html', label: '🧑‍💼 Staff', cls: 'btn btn-outline btn-sm' },
    { key: 'suppliers', href: 'suppliers.html', label: '🏭 Suppliers', cls: 'btn btn-outline btn-sm' },
    { key: 'reports', href: 'reports.html', label: '📊 Reports', cls: 'btn btn-outline btn-sm' },
];

function getSharedNavKey() {
    const page = (location.pathname.split('/').pop() || '').toLowerCase();
    if (page === 'index.html' || page === '' || page === '/') return 'index';
    if (page.startsWith('customer')) return 'customers';
    if (page.startsWith('sale-detail')) return 'sales';
    if (page.startsWith('sales')) return 'sales';
    if (page.startsWith('collection')) return 'collections';
    if (page.startsWith('expense')) return 'expenses';
    if (page.startsWith('product')) return 'products';
    if (page.startsWith('staff')) return 'staff';
    if (page.startsWith('supplier')) return 'suppliers';
    if (page.startsWith('report')) return 'reports';
    return '';
}

function renderSharedNavLinks(activeKey = '') {
    return SHARED_NAV_ITEMS.map(item => {
        const isActive = item.key === activeKey;
        const cls = isActive ? item.cls.replace('btn-outline', 'btn-primary').replace('btn-ghost', 'btn-primary') : item.cls;
        return `<a href="${esc(item.href)}" class="${cls}">${item.label}</a>`;
    }).join('');
}

function applySharedNavbar() {
    const box = document.querySelector('.navbar-actions');
    if (!box) return;
    box.innerHTML = renderSharedNavLinks(getSharedNavKey());
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', applySharedNavbar);
    document.addEventListener('DOMContentLoaded', applyFeatureVisibility);
} else {
    applySharedNavbar();
    applyFeatureVisibility();
}

// ============================================
// TOAST NOTIFICATION
// ============================================
function showToast(msg, type = 'success') {
    let container = document.getElementById('toastContainer');
    if (!container) {
        container = document.createElement('div');
        container.id = 'toastContainer';
        container.style.cssText = 'position:fixed;bottom:24px;right:24px;z-index:9999;display:flex;flex-direction:column;gap:8px;';
        document.body.appendChild(container);
    }
    const t = document.createElement('div');
    const colors = { success: '#10b981', error: '#ef4444', warning: '#f59e0b', info: '#3b82f6' };
    t.style.cssText = `padding:12px 18px;border-radius:8px;color:white;font-weight:600;font-size:12px;animation:slideUp 0.3s ease;box-shadow:0 10px 25px rgba(0,0,0,0.1);max-width:380px;background:${colors[type] || colors.info};`;
    t.textContent = msg;
    container.appendChild(t);
    setTimeout(() => { t.style.opacity = '0'; t.style.transition = 'opacity 0.3s'; setTimeout(() => t.remove(), 300); }, 2500);
}

